def read_settings(text):
    settings = {}
    required_keys = {'endpoint', 'enabled'}
    for line in text.splitlines():
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue
        if '=' not in stripped_line:
            raise ValueError(f"Malformed line: {stripped_line}")
        key, value = stripped_line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if key in settings:
            raise ValueError(f"Duplicate key: {key}")
        settings[key] = value
    if not required_keys.issubset(settings.keys()):
        missing_keys = required_keys - settings.keys()
        raise ValueError(f"Missing required keys: {missing_keys}")
    if 'enabled' in settings and settings['enabled'].lower() not in ('true', 'false'):
        raise ValueError(f"Invalid value for 'enabled': {settings['enabled']}")
    settings['enabled'] = bool(settings['enabled'].lower() == 'true')
    return settings
